def en_az_bozuk(miktar, bozuklar):
    dp = [0] + [float("inf")] * miktar
    for m in range(1, miktar + 1):
        for b in bozuklar:
            if b <= m:
                dp[m] = min(dp[m], dp[m - b] + 1)
    return dp[miktar]

print(en_az_bozuk(6, [1, 3, 4]))

def canta(kapasite, agirlik, deger):
    dp = [0] * (kapasite + 1)
    for a, d in zip(agirlik, deger):
        for c in range(kapasite, a - 1, -1):
            dp[c] = max(dp[c], dp[c - a] + d)
    return dp[kapasite]

print(canta(5, [1, 3, 4], [15, 20, 30]))
